#!/usr/bin/env node
'use strict';

// Device sweep for the "Generated by Claude Code" footer the cloud GitHub route appends. Runs on a
// computer whose `gh` sign-in edits without adding the footer, with no AI step, so a scheduled task can
// call it. It scans one or more repositories (issue and pull request comments, review comments, review
// bodies, issue and pull request bodies), reports every post that ends with the footer and, with
// --apply, edits each one to the same text minus the footer and reads it back.
//
// Only posts written by the signed-in account are edited unless --any-author is given; others are
// listed as skipped. Without --apply nothing is written. Each edit re-reads the post first and skips
// it (SKIPPED_CHANGED) if it changed since the scan, then reads it back and reports MISMATCH when
// GitHub stored anything other than the text sent.
//
// Usage: node repo/scripts/toolkit-github-footer-sweep.cjs --repo <owner/name> [--repo ...] [--since <ISO time>] [--apply] [--any-author] [--json]
// Exit: 0 no post with the footer; 3 posts with the footer found and none cleaned (a report-only run,
// or every one skipped); 4 at least one post cleaned and nothing failed; 1 a scan, edit or read-back
// failed (FAILED, STILL_FOOTED or MISMATCH); 2 bad arguments.

const { execFileSync } = require('node:child_process');
const { hasFooter, stripFooter } = require('./toolkit-github-footer-guard.cjs');

const USAGE = 'Usage: node repo/scripts/toolkit-github-footer-sweep.cjs --repo <owner/name> [--repo ...] [--since <ISO time>] [--apply] [--any-author] [--json]';
const REPOSITORY = /^[\w.-]+\/[\w.-]+$/;

function parseArgs(argv) {
  const options = { repos: [], since: null, apply: false, anyAuthor: false, json: false };
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === '--repo') {
      const value = argv[index += 1];
      if (!REPOSITORY.test(value || '')) throw new Error(`--repo needs owner/name, got ${value === undefined ? 'nothing' : JSON.stringify(value)}`);
      options.repos.push(value);
    } else if (arg === '--since') {
      const value = argv[index += 1];
      if (!value || Number.isNaN(Date.parse(value))) throw new Error('--since needs an ISO time such as 2026-10-01T00:00:00Z');
      options.since = new Date(value).toISOString();
    } else if (arg === '--apply') options.apply = true;
    else if (arg === '--any-author') options.anyAuthor = true;
    else if (arg === '--json') options.json = true;
    else throw new Error(`unknown argument ${JSON.stringify(arg)}`);
  }
  if (!options.repos.length) throw new Error('give at least one --repo');
  return options;
}

function defaultGh(args, input) {
  return execFileSync('gh', args, { encoding: 'utf8', input, stdio: ['pipe', 'pipe', 'pipe'], maxBuffer: 256 * 1024 * 1024, windowsHide: true });
}

const FIELDS = '{id, number, body, user: .user.login, html_url, updated_at}';

// One JSON object per line from a paginated list.
function list(gh, endpoint) {
  const out = gh(['api', '--paginate', endpoint, '--jq', `.[] | ${FIELDS} | @json`]);
  return out.split(/\r?\n/).filter(Boolean).map((line) => JSON.parse(line));
}

function getOne(gh, endpoint) {
  return JSON.parse(gh(['api', endpoint, '--jq', `${FIELDS} | @json`]).trim());
}

const query = (since, extra = '') => `per_page=100${since ? `&since=${encodeURIComponent(since)}` : ''}${extra}`;

// Every post in a repository that ends with the footer, with the endpoint and method that edit it.
function findFooted(gh, repo, since) {
  const found = [];
  const add = (kind, item, path, method) => { if (hasFooter(item.body)) found.push({ kind, repo, id: item.id, url: item.html_url, author: item.user, body: item.body, path, method }); };
  for (const item of list(gh, `repos/${repo}/issues/comments?${query(since)}`)) add('issue_comment', item, `repos/${repo}/issues/comments/${item.id}`, 'PATCH');
  for (const item of list(gh, `repos/${repo}/pulls/comments?${query(since)}`)) add('review_comment', item, `repos/${repo}/pulls/comments/${item.id}`, 'PATCH');
  for (const item of list(gh, `repos/${repo}/issues?${query(since, '&state=all')}`)) {
    add(/\/pull\/\d+$/.test(item.html_url || '') ? 'pull_request' : 'issue', item, `repos/${repo}/issues/${item.number}`, 'PATCH');
  }
  // Reviews have no repository-wide list: read them per pull request updated in the window.
  for (const pull of list(gh, `repos/${repo}/pulls?per_page=100&state=all&sort=updated&direction=desc`)) {
    if (since && pull.updated_at && pull.updated_at < since) continue;
    for (const item of list(gh, `repos/${repo}/pulls/${pull.number}/reviews?per_page=100`)) {
      add('review', item, `repos/${repo}/pulls/${pull.number}/reviews/${item.id}`, 'PUT');
    }
  }
  return found;
}

function sweep(options, deps = {}) {
  const gh = deps.gh || defaultGh;
  const login = options.anyAuthor ? null : gh(['api', 'user', '--jq', '.login']).trim();
  const results = [];
  for (const repo of options.repos) {
    let footed;
    try { footed = findFooted(gh, repo, options.since); }
    catch (error) { results.push({ repo, kind: 'scan', status: 'FAILED', detail: firstLine(error) }); continue; }
    for (const post of footed) {
      const row = { repo, kind: post.kind, url: post.url, author: post.author };
      const body = stripFooter(post.body);
      if (login && post.author !== login) { results.push({ ...row, status: 'SKIPPED_OTHER_AUTHOR' }); continue; }
      // GitHub refuses an empty comment or review; an issue or pull request body may be empty.
      if (!body.trim() && !EMPTY_ALLOWED.has(post.kind)) { results.push({ ...row, status: 'SKIPPED_EMPTY_AFTER_STRIP' }); continue; }
      if (!options.apply) { results.push({ ...row, status: 'FOUND' }); continue; }
      try {
        // Re-read just before writing, so an edit made since the scan is never overwritten.
        if (getOne(gh, post.path).body !== post.body) { results.push({ ...row, status: 'SKIPPED_CHANGED' }); continue; }
        gh(['api', '-X', post.method, post.path, '--input', '-'], JSON.stringify({ body }));
        const back = getOne(gh, post.path);
        const status = hasFooter(back.body) ? 'STILL_FOOTED' : (normalise(back.body) === normalise(body) ? 'CLEANED' : 'MISMATCH');
        results.push({ ...row, status });
      } catch (error) {
        results.push({ ...row, status: 'FAILED', detail: firstLine(error) });
      }
    }
  }
  return results;
}

// The first line of an error, without the request it was made for.
function firstLine(error) {
  const text = String(error?.stderr || error?.message || error || '').trim();
  return text.split(/\r?\n/)[0].slice(0, 200) || 'failed';
}

const EMPTY_ALLOWED = new Set(['issue', 'pull_request']);
// Line endings and trailing whitespace GitHub may change on its own.
const normalise = (body) => String(body ?? '').replace(/\r\n/g, '\n').trimEnd();

const FAILED = new Set(['FAILED', 'STILL_FOOTED', 'MISMATCH']);
const EXIT = Object.freeze({ CLEAN: 0, FAILED: 1, USAGE: 2, FOUND: 3, FIXED: 4 });

// 1 when anything failed, else 4 when a post was cleaned, else 3 when footers were found (and left),
// else 0.
function exitCode(results) {
  if (results.some((row) => FAILED.has(row.status))) return EXIT.FAILED;
  if (results.some((row) => row.status === 'CLEANED')) return EXIT.FIXED;
  if (results.length) return EXIT.FOUND;
  return EXIT.CLEAN;
}

function main(argv = process.argv.slice(2), deps = {}) {
  const out = deps.stdout || ((text) => process.stdout.write(text));
  const err = deps.stderr || ((text) => process.stderr.write(text));
  let options;
  try { options = parseArgs(argv); }
  catch (error) { err(`${error.message}\n${USAGE}\n`); return 2; }
  let results;
  try { results = sweep(options, deps); }
  catch (error) { err(`GitHub footer sweep could not start: ${firstLine(error)}\n`); return 1; }
  if (options.json) out(`${JSON.stringify({ apply: options.apply, since: options.since, results })}\n`);
  else {
    for (const row of results) out(`${row.status} ${row.kind} ${row.url || row.repo}${row.author ? ` (${row.author})` : ''}${row.detail ? `: ${row.detail}` : ''}\n`);
    const counts = results.reduce((all, row) => ({ ...all, [row.status]: (all[row.status] || 0) + 1 }), {});
    const summary = Object.entries(counts).map(([status, count]) => `${count} ${status}`).join(', ') || 'no posts with the footer';
    out(`GitHub footer sweep (${options.apply ? 'apply' : 'report only'}) of ${options.repos.join(', ')}: ${summary}\n`);
  }
  return exitCode(results);
}

if (require.main === module) process.exitCode = main();

module.exports = { parseArgs, findFooted, sweep, main, exitCode, EXIT, USAGE };
